window.THREADS["176627"] = {"tid": "176627", "title": "3D动画【AANiX】大师的2021年-2026年的所有作品", "category": "动漫游戏", "typeid": "12", "author": "永恒的米乐", "uid": "291056", "date": "2026-9-25 09:48:50", "views": 44410, "replies": 15, "pages_fetched": 2, "post_count": 16, "cover": "assets/images/176627/XpWfdcZ.gif", "all_images": ["assets/images/176627/XpWfdcZ.gif", "assets/images/176627/12eI0O7.gif", "assets/images/176627/2J2zk6B.gif", "assets/images/176627/Kshewta.gif", "assets/images/176627/kzPYFpp.gif", "assets/images/176627/zcZgBmm.gif", "assets/images/176627/Eb35I53.gif", "assets/images/176627/lzmvh1i.gif", "assets/images/176627/ACkM65X.gif", "assets/images/176627/CN4UMx7.gif", "assets/images/176627/5MRNOpJ.gif", "assets/images/176627/8UIgURW.gif", "assets/images/176627/NA0SLCQ.gif", "assets/images/176627/fskbZD8.gif", "assets/images/176627/eFnv5kb.gif", "assets/images/176627/kVR1b9a.gif", "assets/images/176627/hCOp7Zo.gif", "assets/images/176627/GG9dgHt.gif", "assets/images/176627/ayGuvDU.gif", "assets/images/176627/gnFstwI.gif", "assets/images/176627/mRvFK0k.gif", "assets/images/176627/GJHYJsk.gif", "assets/images/176627/F8Qlwcg.gif", "assets/images/176627/Egi2XnZ.gif"], "pan": [{"key": "baidu", "label": "百度网盘"}, {"key": "xunlei", "label": "迅雷网盘"}], "pan_floor": [], "article": {"author": "永恒的米乐", "uid": "291056", "avatar": "", "date": "2026-9-25 09:48:50", "html": "<font face=\"微軟雅黑\"><font size=\"5\"><strong>AANiX是一位3D艺术家，制作各种长度的视频游戏角色动画，例如：</strong></font></font><br />\n<font face=\"微軟雅黑\"><font size=\"5\"><strong>《英雄联盟》KDA女团</strong></font></font><strong>、《生化危机》、《守望先锋》、《最终幻想》等。他擅长多性向内容，常涉及跨种族题材。</strong><br />\n<font face=\"微軟雅黑\"><font size=\"5\"><strong>这是</strong></font></font><strong>AANiX大师</strong><font face=\"微軟雅黑\"><font size=\"5\"><strong>2021年开始，到2026年6月份的所有作品。总共有35G，按照每年的每个月份来压缩了。</strong></font></font><br />\n<br />\n<br />\n<font face=\"微軟雅黑\"><font size=\"5\"><strong>这大师的作品有各个游戏里的女角色，目前街头霸王的春丽是他最喜欢的角色，已经连续出了4个春丽的小长篇视频。<br />\n</strong></font></font><font face=\"微軟雅黑\"><font size=\"5\"><strong><br />\n</strong></font></font><font face=\"微軟雅黑\"><font size=\"5\"><strong><strong>AANiX</strong>大师制作的视频有短篇有小长篇，短篇是几十秒，小长篇8分钟左右，小长篇有点对话和剧情，不过就跟欧美AV一样，剧情都是象征性的来个开场，然后就进行打桩。<br />\n</strong></font></font><font face=\"微軟雅黑\"><br />\n<font size=\"5\"><strong>这个作者的制作的视频里的男主有黑人有白人</strong></font><br />\n<font size=\"5\"><strong><strong>过气了几年的偶像女团 KDA </strong></strong></font><br />\n<font size=\"7\"><font color=\"#ff0000\"><strong>KDA女团 </strong></font></font><font size=\"7\"><font color=\"#ff0000\"><strong>阿狸</strong></font></font><br />\n</font><br />\n<img src=\"assets/images/176627/XpWfdcZ.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n<br />\n<img src=\"assets/images/176627/12eI0O7.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/176627/2J2zk6B.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<strong>KDA女团 卡莎</strong><br />\n<img src=\"assets/images/176627/Kshewta.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/176627/kzPYFpp.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<strong>KDA女团 阿卡丽</strong><br />\n<img src=\"assets/images/176627/zcZgBmm.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/176627/Eb35I53.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/176627/lzmvh1i.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<strong>KDA女团 伊芙琳</strong><br />\n<img src=\"assets/images/176627/ACkM65X.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/176627/CN4UMx7.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/176627/5MRNOpJ.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<strong>KDA女团 外聘人员 萨拉芬妮</strong><br />\n<img src=\"assets/images/176627/8UIgURW.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/176627/NA0SLCQ.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<img src=\"assets/images/176627/fskbZD8.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n\n<br />\n<font face=\"微軟雅黑\"><font size=\"7\"><font color=\"#ff0000\"><strong>不知火舞</strong></font></font></font><br />\n<img src=\"assets/images/176627/eFnv5kb.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n\n<br />\n<font face=\"微軟雅黑\"><font size=\"7\"><font color=\"#ff0000\"><strong>老头环 梅琳娜</strong></font></font></font><br />\n<img src=\"assets/images/176627/kVR1b9a.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n\n<br />\n<font face=\"微軟雅黑\"><font size=\"7\"><font color=\"#ff0000\"><strong>最终幻想7 玛姆<br />\n</strong></font></font></font><br />\n<img src=\"assets/images/176627/hCOp7Zo.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n\n<br />\n<font face=\"微軟雅黑\"><font size=\"7\"><font color=\"#ff0000\"><strong>生化危机 艾达王</strong></font></font></font><br />\n<img src=\"assets/images/176627/GG9dgHt.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n\n<br />\n<font face=\"微軟雅黑\"><font size=\"7\"><font color=\"#ff0000\"><strong>猎天使魔女 贝优妮塔</strong></font></font></font><br />\n<img src=\"assets/images/176627/ayGuvDU.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n<font face=\"微軟雅黑\"><font size=\"7\"><font color=\"#ff0000\"><strong>2B</strong></font></font></font><br />\n<img src=\"assets/images/176627/gnFstwI.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n\n<br />\n<font face=\"微軟雅黑\"><font size=\"7\"><font color=\"#ff0000\"><strong>生化危机8 蒂米特雷斯库夫人</strong></font></font></font><br />\n<img src=\"assets/images/176627/mRvFK0k.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n\n<br />\n<font face=\"微軟雅黑\"><font size=\"7\"><font color=\"#ff0000\"><strong>第一后裔 弗蕾娜</strong></font></font></font><br />\n<img src=\"assets/images/176627/GJHYJsk.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n\n<br />\n<font face=\"微軟雅黑\"><font size=\"7\"><font color=\"#ff0000\"><strong>街头霸王 嘉米</strong></font></font></font><br />\n<img src=\"assets/images/176627/F8Qlwcg.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n\n<br />\n<font face=\"微軟雅黑\"><font size=\"7\"><font color=\"#ff0000\"><strong>街头霸王 春丽</strong></font></font></font><br />\n<img src=\"assets/images/176627/Egi2XnZ.gif\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n\n<br />\n\n<br />\n\n<br />\n\n<br />\n\n<br />\n\n<br />\n\n<br />\n<font size=\"5\">#########################################</font><br />\n<font size=\"5\"><br />\n</font><br />\n<strong><font size=\"5\">百度网盘</font><font size=\"5\"><font color=\"#336699\">链接</font></font><font color=\"#336699\"><font size=\"5\">: </font></font><font size=\"5\"><font color=\"#336699\">: <a href=\"https://pan.baidu.com/s/1Tqqqfnr6NSVXiCTm_bbKOw\" target=\"_blank\">https://pan.baidu.com/s/1Tqqqfnr6NSVXiCTm_bbKOw</a></font></font></strong><br />\n<font size=\"5\"><font color=\"#336699\"><strong>提取码: jy4p</strong><br />\n</font></font><br />\n<font size=\"5\"><br />\n<strong>迅雷链接：</strong></font><font size=\"5\"><font color=\"#0000ff\"><strong>https://pan.xunlei.com/s/VP2LDtLqoFBWxhmNfU7onsiiA1</strong></font></font><br />\n<font size=\"5\"><strong>提取码：<font color=\"#0000ff\">md8s</font></strong><br />\n<br />\n</font><br />\n<font size=\"5\">#########################################<br />\n</font><br />\n<div align=\"left\"><font size=\"5\">为了防止太快被炸，我压缩包都弄成分卷压缩</font></div><div align=\"left\"><font size=\"5\">分卷压缩指的是，这种压缩包的后缀是7z.001和7z.002。想解压，则是需要将那2个500MB的压缩包都下载在同一个文件夹内，然后点击压缩包7z.001来解压就行了（不需要修改后缀）。</font></div><div align=\"left\"><font size=\"5\"><br />\n</font></div><div align=\"left\"><font size=\"5\">值得注意的是，很多人解压的时候将后缀最后面的001、002删了再解压，这样会解压失败</font></div><div align=\"left\"><font size=\"5\">解压完分卷压缩包后，会出现7z7文件，将7z7改成7z后再解压一遍就行了</font></div>", "images": ["assets/images/176627/XpWfdcZ.gif", "assets/images/176627/12eI0O7.gif", "assets/images/176627/2J2zk6B.gif", "assets/images/176627/Kshewta.gif", "assets/images/176627/kzPYFpp.gif", "assets/images/176627/zcZgBmm.gif", "assets/images/176627/Eb35I53.gif", "assets/images/176627/lzmvh1i.gif", "assets/images/176627/ACkM65X.gif", "assets/images/176627/CN4UMx7.gif", "assets/images/176627/5MRNOpJ.gif", "assets/images/176627/8UIgURW.gif", "assets/images/176627/NA0SLCQ.gif", "assets/images/176627/fskbZD8.gif", "assets/images/176627/eFnv5kb.gif", "assets/images/176627/kVR1b9a.gif", "assets/images/176627/hCOp7Zo.gif", "assets/images/176627/GG9dgHt.gif", "assets/images/176627/ayGuvDU.gif", "assets/images/176627/gnFstwI.gif", "assets/images/176627/mRvFK0k.gif", "assets/images/176627/GJHYJsk.gif", "assets/images/176627/F8Qlwcg.gif", "assets/images/176627/Egi2XnZ.gif"]}, "comments": [{"floor": 2, "author": "zglgogogo", "uid": "353096", "avatar": "", "date": "", "html": "这个AI横行的年代，这3D没有任何价值了", "images": []}, {"floor": 3, "author": "秦始皇摸电线", "uid": "531777", "avatar": "", "date": "", "html": "我不同意2楼观点，不要用现在的时代浮躁去讽刺过去的星星，人类的烟花固然美丽，但是天空因为有群星，才显得闪耀，更不要嘲讽辛苦收集资源的大佬，在论坛里，这是一个司机最基本的素质~令祝论坛里所有的大佬中秋快乐~<img src=\"static/image/smiley/javbus/50.png\" smilieid=\"131\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" /><img src=\"static/image/smiley/javbus/50.png\" smilieid=\"131\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" /><img src=\"static/image/smiley/javbus/50.png\" smilieid=\"131\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 4, "author": "waerha", "uid": "677144", "avatar": "", "date": "", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4928358&amp;ptid=176627\" target=\"_blank\"><font color=\"#999999\">zglgogogo 發表於 2026-9-25 10:10</font></a></font><br />\n这个AI横行的年代，这3D没有任何价值了</blockquote></div><br />\n恕我不能苟同，我下了几百G的AI。现在反而审美疲劳了，虽然剧情有意思，但人物模型同质化严重。上乘的3D制作模型精美，满足幻想。目前看来还没到退出市场的时候。", "images": []}, {"floor": 5, "author": "星逆", "uid": "267525", "avatar": "", "date": "", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4928358&amp;ptid=176627\" target=\"_blank\"><font color=\"#999999\">zglgogogo 發表於 2026-9-25 10:10</font></a></font><br />\n这个AI横行的年代，这3D没有任何价值了</blockquote></div><br />\n人类制作的作品对于细节、观众心理的把握是目前AI生成的生成物暂时还无法达到的。AI目前还处在咋一看还行，量大还管饱的阶段，但是看多了之后就会产生审美疲劳。", "images": []}, {"floor": 6, "author": "q170103735", "uid": "375920", "avatar": "", "date": "", "html": "AI作品初看觉得新鲜，多看几部就被各种穿模和同质化的脸劝退了<br />\n还是这种精致的3D动画耐看", "images": []}, {"floor": 7, "author": "a90120411", "uid": "174390", "avatar": "", "date": "", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4928358&amp;ptid=176627\" target=\"_blank\"><font color=\"#999999\">zglgogogo 發表於 2026-9-25 10:10</font></a></font><br />\n这个AI横行的年代，这3D没有任何价值了</blockquote></div><br />\n如果是这样的话，那再过几年，人类也没有任何价值了。", "images": []}, {"floor": 8, "author": "月官官", "uid": "432282", "avatar": "", "date": "", "html": "画风有点硬，柔和点就好了", "images": []}, {"floor": 9, "author": "putong", "uid": "644063", "avatar": "", "date": "", "html": "以前要等好久才有一集产出，ai现在方便多了", "images": []}, {"floor": 10, "author": "sakura76000", "uid": "127328", "avatar": "", "date": "", "html": "密码是多少？javbus不对啊", "images": []}, {"floor": 11, "author": "bmw499", "uid": "307597", "avatar": "", "date": "", "html": "特意登录表示下感谢 不知道是不是有剧情的 有剧情最好了", "images": []}, {"floor": 12, "author": "3222594268", "uid": "374527", "avatar": "", "date": "", "html": "有这技术再配合AI的话，岂不无敌了", "images": []}, {"floor": 13, "author": "肥仔弟弟", "uid": "703222", "avatar": "", "date": "", "html": "老哥有心了<img src=\"static/image/smiley/javbus/15.png\" smilieid=\"92\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 14, "author": "mark12138", "uid": "473713", "avatar": "", "date": "", "html": "感谢分享，这位大师的作品最大的特点就是喜欢多杆进洞，我一直想说这种玩法看上去视觉冲击力是挺强的，但是仔细想想这么多根杆子在互相摩擦不觉得怪怪的吗哈哈<img src=\"static/image/smiley/javbus/29.png\" smilieid=\"107\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" /><img src=\"static/image/smiley/javbus/29.png\" smilieid=\"107\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 15, "author": "yjr1124", "uid": "392668", "avatar": "", "date": "共 2 頁", "html": "谢谢作者分享, AI作品太油腻了, 我还是喜欢这种手作作品", "images": []}, {"floor": 16, "author": "gundan0083", "uid": "483490", "avatar": "", "date": "共 2 頁", "html": "看了AI短剧了，你会发现任务的表情同质化非常严重，都是一个表情，一套动作，好的3D，人物建模，表情要比AI高级得多。只能说AI要想超过3D，还是有一段路要走。", "images": []}]};
window.THREADS["177859"] = {"tid": "177859", "title": "纸飞机PC被诈骗，现在诈骗犯被抓了警察找小弟去做笔录", "category": "交流", "typeid": "7", "author": "gy6858038", "uid": "119409", "date": "2026-10-24 15:45:55", "views": 11850, "replies": 42, "pages_fetched": 3, "post_count": 43, "cover": "", "all_images": [], "pan": [], "pan_floor": [], "article": {"author": "gy6858038", "uid": "119409", "avatar": "", "date": "2026-10-24 15:45:55", "html": "之前刚用纸飞机不太懂，刚好在外地出差，想去尝试一下，结果到了楼下让给各种保证及和预付款，转了两笔以后意识到有问题就撤退了，人都没见到。但是现在警察通知我说诈骗犯抓到了，让我配合去做笔录，说被骗的钱可以退给我，小弟并不在乎这一点钱，主要担心自己本身的行为可能会对自己有影响，不知道要咋办，求大哥们给支支招。", "images": []}, "comments": [{"floor": 2, "author": "328500734", "uid": "391678", "avatar": "", "date": "2026-10-24 15:47:23", "html": "如实说&nbsp;&nbsp;就是 最安全的 千万别想否认，", "images": []}, {"floor": 3, "author": "batmancar", "uid": "308886", "avatar": "", "date": "2026-10-24 15:47:37", "html": "你报警了?这警察也是一伙的吧", "images": []}, {"floor": 4, "author": "gy6858038", "uid": "119409", "avatar": "", "date": "2026-10-24 15:48:27", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4967503&amp;ptid=177859\" target=\"_blank\"><font color=\"#999999\">batmancar 發表於 2026-10-24 15:47</font></a></font><br />\n你报警了?这警察也是一伙的吧</blockquote></div><br />\n我没报警，是警察主动联系的我，说诈骗犯被抓了，在转账记录里面看到了我", "images": []}, {"floor": 5, "author": "雷锋老湿", "uid": "663666", "avatar": "", "date": "2026-10-24 15:49:59", "html": "上网问有啥用，看公安机关怎么处理<br />\n他可以放你一马也可以算你嫖娼罚款拘留，因为按法律来说你有了主观意愿就算你嫖娼，不一定非要发生关系才算嫖娼", "images": []}, {"floor": 6, "author": "batmancar", "uid": "308886", "avatar": "", "date": "2026-10-24 15:54:41", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4967506&amp;ptid=177859\" target=\"_blank\"><font color=\"#999999\">雷锋老湿 發表於 2026-10-24 15:49</font></a></font><br />\n上网问有啥用，看公安机关怎么处理<br />\n他可以放你一马也可以算你嫖娼罚款拘留，因为按法律来说你有了主观意愿 ...</blockquote></div><br />\n有想法不算,有转账但没性行为算情节较轻,一样有几率治安处罚", "images": []}, {"floor": 7, "author": "ysdddn", "uid": "196000", "avatar": "", "date": "2026-10-24 16:04:05", "html": "你没报警，警察怎么会找的到你<br />\n大概率是一伙的来诈骗你吧", "images": []}, {"floor": 8, "author": "雷锋老湿", "uid": "663666", "avatar": "", "date": "2026-10-24 16:11:57", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4967510&amp;ptid=177859\" target=\"_blank\"><font color=\"#999999\">batmancar 發表於 2026-10-24 15:54</font></a></font><br />\n有想法不算,有转账但没性行为算情节较轻,一样有几率治安处罚</blockquote></div><br />\n我说的有想法肯定是说up这种已经叫人上门或转账的情况，单纯在脑子里想肯定不算啊，你以为警察是神仙啊还知道你想什么", "images": []}, {"floor": 9, "author": "听雨秀才", "uid": "633632", "avatar": "", "date": "2026-10-24 16:28:44", "html": "<i class=\"pstatus\"> 本帖最後由 听雨秀才 於 2026-10-24 16:30 編輯 </i><br />\n<br />\n千万别去 要么钓鱼的，要么是噶腰子的，我朋友就是被反诈骗过去，然后人家直接给你烤起来，然后喜提小黑屋七天，补充一句，无论你骗没被骗，钱是不会还你的，关你是一定会关你的，", "images": []}, {"floor": 10, "author": "gy6858038", "uid": "119409", "avatar": "", "date": "2026-10-24 16:36:37", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4967552&amp;ptid=177859\" target=\"_blank\"><font color=\"#999999\">听雨秀才 發表於 2026-10-24 16:28</font></a></font><br />\n千万别去 要么钓鱼的，要么是噶腰子的，我朋友就是被反诈骗过去，然后人家直接给你烤起来，然后喜提小黑屋 ...</blockquote></div><br />\n我知道这种肯定不会还我钱，但我担心我一直不去后面也会搞我<br />", "images": []}, {"floor": 11, "author": "zebraoo00", "uid": "341710", "avatar": "", "date": "2026-10-24 16:38:15", "html": "千万别去，去了百分百行政拘留，各种恐吓你逼你承认嫖娼。再打电话就说没转过钱，对方要是说查到你有转账记录，就说什么都不清楚，之前手机中过毒，啥都不知道，总之不管对方如何说，什么都别承认。", "images": []}, {"floor": 12, "author": "江枫渔火", "uid": "330364", "avatar": "", "date": "2026-10-24 16:50:24", "html": "除非是大钱值得你冒险，不然千万不要去，绝对会拿你充指标", "images": []}, {"floor": 13, "author": "ZKLZ0", "uid": "312155", "avatar": "", "date": "2026-10-24 16:54:03", "html": "嫖资根本不可能退给你。。。大概率坦白从宽牢底坐穿。。", "images": []}, {"floor": 14, "author": "SIUKEUNG15", "uid": "491838", "avatar": "", "date": "2026-10-24 17:01:49", "html": "我个人观点:嫖资大概率不会退的。大概率警察常规例行流程，钓鱼执法，要你去警察局认罪，交罚金后可能退款。在中国大多数都是坦白伏法，当作不知道，警察大概率不会上门执法，警察没这么闲。仅供参考！！！", "images": []}, {"floor": 15, "author": "听雨秀才", "uid": "633632", "avatar": "", "date": "2026-10-24 17:02:00", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4967560&amp;ptid=177859\" target=\"_blank\"><font color=\"#999999\">gy6858038 發表於 2026-10-24 16:36</font></a></font><br />\n我知道这种肯定不会还我钱，但我担心我一直不去后面也会搞我</blockquote></div><br />\n别去就是了，这种都是炸你，因为就一条转账，你去就是自首。", "images": []}, {"floor": 16, "author": "qwzxllww", "uid": "254112", "avatar": "", "date": "2026-10-24 18:56:39", "html": "不在乎这点钱就别去别理就行了。一旦去了做了笔录，那就由不得你了。嫖娼未遂也是可以处罚的。没必要。你不去就没办法搞你", "images": []}, {"floor": 17, "author": "wangyongalfred", "uid": "311858", "avatar": "", "date": "2026-10-24 19:14:36", "html": "<i class=\"pstatus\"> 本帖最後由 wangyongalfred 於 2026-10-24 19:20 編輯 </i><br />\n<br />\n别去 钱就当没了。真要按PC罪行政拘留你，你也没辙。", "images": []}, {"floor": 18, "author": "朝你大垮捏一把", "uid": "594616", "avatar": "", "date": "2026-10-24 20:20:34", "html": "别去，你连对面是不是真jc都不确定，别管就行", "images": []}, {"floor": 19, "author": "q6755607", "uid": "304946", "avatar": "", "date": "2026-10-24 23:18:01", "html": "让他滚，别太把帽子当回事", "images": []}, {"floor": 20, "author": "gordon_chin", "uid": "400820", "avatar": "", "date": "2026-10-24 23:37:20", "html": "<i class=\"pstatus\"> 本帖最後由 gordon_chin 於 2026-10-24 23:39 編輯 </i><br />\n<br />\n首先，你要先确定对方真是正式jc，否则，免谈！要是真jc，对方会没有你相关资料？？？你到底在纸飞机上面注册了些什么内容？？？？如果是真实内容那就必须在警察局正经的地方，协助调查，否则，真警察会没有你的资料？？？<br />\n我告诉你我多年前一个经历，那次在云南旅游，和一个诈骗嫌疑人，一前一后进入高铁站的安检区，被人脸系统识别了，回到家里，过来两周吧，辖区派出所就来电话要我去协助调查了，当时接到电话我还以为是诈骗电话，后来，我听出对方的确有当地口音，也允许我到街道的派出所找他，我就判断对方是真jc，那我就去了，就在派出所传达室把jc叫出来，当面聊，幸亏都是本地人（一看身份证就知道了），他向我了解情况，我向他了解出什么事情了，，，，，聊完了就回家。当然了，你情况和我不太一样，你有“未遂”事实，但无论怎样，先确定对方是真警察再决定下一步，但个人还是建议不要去，钱是身外之物，要是小地方，不正经jc硬把你给拘了，也是没辙(有背景当我没说）。", "images": []}, {"floor": 21, "author": "liang9726", "uid": "297973", "avatar": "", "date": "2026-10-25 02:47:30", "html": "哦，只要不是警察上门找你的，你就直接拒绝就行了，不是啥事。我有过一次，说是诈骗让我去登记笔录，我开始以为这个派出所的电话是假的呢，先开骂，听了内容之后发现应该是真派出所打来的，就说忙我不打算追究不去行不行，那边就挂了。", "images": []}, {"floor": 22, "author": "DickBest", "uid": "445178", "avatar": "", "date": "2026-10-25 03:07:10", "html": "别去，别认，认了就是嫖娼，要被拘留的。", "images": []}, {"floor": 23, "author": "妇女之光", "uid": "126572", "avatar": "", "date": "2026-10-25 05:56:20", "html": "首先付订金的不能说都是骗子，但是概率很大，然后记得用现金，现金，现金", "images": []}, {"floor": 24, "author": "again", "uid": "23929", "avatar": "", "date": "2026-10-25 09:21:43", "html": "你是有多蠢通过电报上找的资源，还预付定金。。论坛里都不知道有多少人和事说过千万不能预付定金，但凡让你付定金的都是骗子。电报上资源虽多，但骗子更多。", "images": []}, {"floor": 25, "author": "XSDLHZX", "uid": "628639", "avatar": "", "date": "2026-10-25 16:34:56", "html": "去了百分百 让你认", "images": []}, {"floor": 26, "author": "隔壁葡萄", "uid": "381035", "avatar": "", "date": "2026-10-25 16:58:00", "html": "好像不是有追诉期，半年，或者就说自己出差，没时间去领，钱不要了，付定金的这种以后别找了，除非是那种老牌高端的外围，普通的基本都不用定金就会来，来了不满意给个打车钱就行", "images": []}, {"floor": 27, "author": "无面", "uid": "353463", "avatar": "", "date": "2026-10-25 17:04:49", "html": "真的警察的话，会上你家门口当面跟你说的，其他的，不要乱信", "images": []}, {"floor": 28, "author": "gy6858038", "uid": "119409", "avatar": "", "date": "2026-10-25 17:23:55", "html": "看完了各位大哥的回复，钱肯定是不要了，去也肯定不会去，telegram账号也注销了，就说自己出差或者钱不需要追回了", "images": []}, {"floor": 29, "author": "giaogiaogiaog", "uid": "638358", "avatar": "", "date": "2026-10-25 18:57:08", "html": "反正是我不会去", "images": []}, {"floor": 30, "author": "拜命三归", "uid": "502086", "avatar": "", "date": "2026-10-26 00:01:39", "html": "嫖娼追溯期是交易时间的6个月，你这种情况如果确定是真JC的话去了百分百是认定嫖娼未遂，拘留3天，当然今年新规可以拘留或罚款，也许罚款也说不定，但最稳妥的方法就是说自己不在本地，离得很远，最好是去香港澳门了，这样一般不会再找你了，毕竟证人不差你一个", "images": []}, {"floor": 31, "author": "ECCODDE", "uid": "413668", "avatar": "", "date": "2026-10-26 00:35:26", "html": "不要转账 <br />\n不要转账<br />\n<img src=\"static/image/smiley/javbus/3.png\" smilieid=\"108\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 32, "author": "pomel88", "uid": "684016", "avatar": "", "date": "2026-10-26 02:21:55", "html": "无需理会，不要过去。要是跟你说你资金异常大概率是喊你去u做笔录的，最好就是说在外地出差没空过去", "images": []}, {"floor": 33, "author": "lau123", "uid": "635166", "avatar": "", "date": "2026-10-26 13:31:26", "html": "让你去不要去，就说人在外地，过段时间回去", "images": []}, {"floor": 34, "author": "sd371219", "uid": "85223", "avatar": "", "date": "2026-10-26 15:01:37", "html": "查查电话号码总可以吧。真的假的都敷衍了事。忙，不去。下次记住不见兔子不撒鹰，现金交易。", "images": []}, {"floor": 35, "author": "nationale", "uid": "650884", "avatar": "", "date": "2026-10-26 21:24:10", "html": "哎，这是明显的局中局啊！", "images": []}, {"floor": 36, "author": "1490534196", "uid": "670661", "avatar": "", "date": "2026-10-26 21:44:42", "html": "千万别去，很大概率是连环诈骗，小钱咱就不要了，问就说不知道，前段时间手机掉了", "images": []}, {"floor": 37, "author": "lwh1006", "uid": "161579", "avatar": "", "date": "2026-10-27 14:50:09", "html": "绝对钓鱼！我之前和朋友打麻将，输了4000给他，我就微信转给他了，后面这货去山头上的赌场被抓，也是派出所打电话给我，先问我是不是和他一起打麻将了，我立马否认，然后又问是不是输了4000给他，我说那是他找我借的钱付货款，还诓我说如果是输给他的可以退，我咬死就是借款，然后一边接派出所的电话，一边拿微信和另外两个一起打麻将的朋友通风报信。后来这个狗东西又喊打麻将，被我们一顿骂，TM你去赌场赌钱被抓，居然把一个月前一起打麻将的都拖下水", "images": []}, {"floor": 38, "author": "这样也挺好", "uid": "568276", "avatar": "", "date": "2026-10-27 16:45:30", "html": "找律师咨询，实在不行让律师去处理", "images": []}, {"floor": 39, "author": "fetishpantyhose", "uid": "338250", "avatar": "", "date": "2026-10-27 16:52:34", "html": "正规警察打电话<br />\n首先表明身份<br />\n我是xx派出所，xxx支队，民警xxx，我的警号：xxxxx，你可以录音，并且公布接受群众监督，但是必须完整五剪辑，不能断章取义，不然追究你的法律责任。<br />\n<br />\n然后大体说一下案情，需要你配合什么，约个时间<br />\n<br />\n不是上述流程基本上都是骗子", "images": []}, {"floor": 40, "author": "306636260", "uid": "337736", "avatar": "", "date": "2026-10-29 13:36:53", "html": "不能去，直觉感觉不能去。。", "images": []}, {"floor": 41, "author": "jasonfatso", "uid": "372592", "avatar": "", "date": "2026-10-29 14:04:09", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4971982&amp;ptid=177859\" target=\"_blank\"><font color=\"#999999\">fetishpantyhose 發表於 2026-10-27 16:52</font></a></font><br />\n正规警察打电话<br />\n首先表明身份<br />\n我是xx派出所，xxx支队，民警xxx，我的警号：xxxxx，你可以录音，并且公布接 ...</blockquote></div><br />\n是这样的", "images": []}, {"floor": 42, "author": "yuepazy", "uid": "622138", "avatar": "", "date": "2026-10-29 14:17:31", "html": "作为 飞机群主 我给你的建议是 可去可不去&nbsp;&nbsp;就别去了 免得播出萝卜带出泥 你也说不在乎那几个钱 打电话给你 你就说在外地出差 要过年才回去 一般过了眼前这段时间 就不会找你了 如果真有事 是不会电话通知的 直接开车上门抓人才对 无论是真警察 还是冒充的 不去就什么事没有 去了你也没事 但是可能要再烧点钱", "images": []}, {"floor": 43, "author": "play海诚", "uid": "666747", "avatar": "", "date": "2026-10-29 14:20:41", "html": "没办法飞机上就是有风险的，当然要玩还是要多渠道扩展", "images": []}]};
